pragma solidity >=0.8.0;
contract EventAddrIdx {
    event AddrIdx(address indexed who, address indexed fixedAddr);
    uint256 public n;
    function ping() external {
        n += 1;
        emit AddrIdx(msg.sender, address(uint160(0x1234)));
    }
    function getN() external view returns (uint256) {
        return n;
    }
}
